args.sparql:
SELECT ?father ?fatherLabel ?place ?placeLabel WHERE {
  ?father dbo:child dbr:Binyamin_Zeev_Kahane .
  ?father dbo:deathPlace ?place .
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER(lang(?fatherLabel) = "en") }
  OPTIONAL { ?place rdfs:label ?placeLabel FILTER(lang(?placeLabel) = "en") }
} LIMIT 20

