    ?father rdfs:label ?fatherLabel
    FILTER(lang(?fatherLabel) = "en")
  }
  OPTIONAL {
    ?place rdfs:label ?placeLabel
    FILTER(lang(?placeLabel) = "en")
  }
}
LIMIT 20

